182	export type NormalizedLead = {
183	  email: string;
184	  domain: string;
185	  fullName: string;
186	  title: string;
187	  business: {
188	    name: string;
189	    category: string;
190	    businessType: string;
191	    website: string;
192	    phone: string;
193	    addressLine: string;
194	    city: string;
195	    region: string;
196	    country: string;
197	    companySize: string;
198	  };
199	  sourceUrl: string;
200	};
