/**
 * ONE-OFF operator script — sets up the "Creator Sponsorship Outreach" cold-email
 * campaign as its OWN segment, distinct from the existing hosting-prospect lists.
 *
 * Reuses the real, tested cold-email engine end to end:
 *   - lib/coldemail/import.ts (ingestLeads) + lib/coldemail/lead-store.ts
 *     (prismaLeadStore) — the SAME idempotent dedup/ingest core scripts/import-leads.ts
 *     uses, so a re-run of this script inserts 0 (safe to re-run).
 *   - db.coldCampaign.create / db.sequenceStep.create — the exact same shape
 *     lib/actions-coldemail.ts's createCampaign()/addSequenceStep() write (those are
 *     "use server" actions gated by requireArea("platform"), which needs a real admin
 *     HTTP request/session to resolve — unusable from a standalone script, same reason
 *     scripts/import-leads.ts bypasses importLeads() and calls ingestLeads() directly).
 *
 * SAFE: writes real Contact/Business/EmailList/ColdCampaign/SequenceStep rows (this is
 * data setup, not sending) but the campaign is created and LEFT in DRAFT status. DRAFT
 * campaigns are invisible to worker/coldemail.ts's send sweep (`where: { status:
 * "SENDING" }`) and to scheduleCampaignSends, so this creates ZERO ColdSend rows and
 * sends ZERO real email. Nothing here calls launchCampaign or flips status.
 *
 * Source data: board card "Full reachout" (cmuh36ziz02l9hl4m7ws5jczm) CSV, cleaned to
 * 328 unique name+email rows (179 blank Palworld-placeholder rows and 6 in-file
 * duplicate emails already removed — see the run log for the exact numbers).
 *
 * "Army of Zeus" (iwizardhax2.0@gmail.com) already got a real one-off send today from
 * santino@nxeon.cloud outside this engine. This system's real, honest way to skip a
 * contact who was already reached — WITHOUT falsely marking them as opted-out via
 * Suppression, and WITHOUT gating on the purely-informational Contact.timesEmailed
 * (confirmed nothing in worker/coldemail.ts reads it) — is simply to never add them to
 * the EmailList a campaign schedules against (scheduleCampaignSends + previewCampaign
 * both scope entirely to db.emailListMember rows for campaign.listId). So Army of Zeus
 * is imported into the lead database (a real, useful record) but NOT added to this
 * campaign's list.
 *
 * Usage: npx tsx scripts/coldemail-creator-campaign-setup.ts
 */
import { readFileSync } from "node:fs";
import { db } from "../lib/db";
import { ingestLeads, type LeadRow } from "../lib/coldemail/import";
import { prismaLeadStore } from "../lib/coldemail/lead-store";

const LEADS_JSON = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/creator-leads-clean.json";
const LIST_NAME = "Creator Sponsorship Outreach — YouTube Creators (2026-09)";
const CAMPAIGN_NAME = "Creator Sponsorship Outreach — YouTube (2026-09)";
const ALREADY_CONTACTED_EMAIL = "iwizardhax2.0@gmail.com"; // Army of Zeus

// Real subject/body from board card "test reachout" (cmugx64kh00djhljsw2o7f1l0),
// [Name]/[Creator Name]/[GAME] converted to this engine's real {{token}} merge syntax
// (see lib/coldemail/sender.ts::contactVars — {{firstName}}/{{fullName}} already
// existed; {{game}} is the new field this branch adds, sourced from Business.category).
//
// The signature placeholder (*Email Signature*) is replaced with a markdown-equivalent
// of the real signature on CompanyMailbox (address='santino@nxeon.cloud').signatureHtml
// — name "Santino", title "Owner, Nxeon", nxeon.cloud + santino@nxeon.cloud + WhatsApp
// links, all real values, not invented. The rich HTML/logo-image version of that
// signature is NOT used verbatim because lib/coldemail/sender.ts::markdownToHtml
// HTML-escapes the entire body by design (see its file-header comment: "raw HTML in
// the body is inert") — a cold-email compliance/safety property, not an oversight, so
// pasting the raw signature HTML in would render as literal escaped tag text, not a
// logo. This also matches the engine's own documented 2026 deliverability philosophy
// (wrapColdEmailHtml's comment: no logo header, no heavy HTML — "a cold email should
// read like a real person's message, not a mass send").
const SUBJECT = "{{fullName}} × Nxeon — Sponsorship Offer";
const BODY_MARKDOWN = `Hey {{firstName}},

I'm Santino, founder of Nxeon, a Canadian cloud hosting company focused on game servers, VPS hosting, and developer infrastructure.

Nxeon supports 50+ different game titles, with {{game}} being one of our most popular. With 13 data centers across 4 continents, we're able to provide fast, reliable service to your viewers around the globe. We also offer 24/7 support and have built a community-driven mod library with 70,000+ mods and over 11.5 billion total downloads.

We've been steadily growing Nxeon and are now launching our creator partner program. I came across your content around {{game}} and really like what you're building, so I wanted to reach out and see if you'd be interested in working together.

For the launch of our creator program, we're offering a highly competitive founding partner offer that we don't expect to keep at this level permanently. We want to give the creators who join us early the strongest possible opportunity to benefit as Nxeon continues to grow.

Here's what we'd like to offer:

40% lifetime recurring commission on customers you refer
50% off their first month for your audience
10% off every month after through your personal creator code
Your own Nxeon Partner Portal to track referrals, customers, renewals, commissions, and payouts
Monthly commission payouts at the beginning of each month
Your own referral link and creator code
Promotional assets and direct support from our team

The 40% commission is lifetime, meaning you continue earning for as long as the customers you refer remain with Nxeon. If they purchase additional services in the future, you can earn from those as well.

This launch offer is specifically designed for our early creator partners. As the program grows, we expect future partnership terms to become more standardized, so joining during the launch gives you access to the most generous version of our creator program.

We're looking to build genuine, long-term relationships with creators rather than simply doing one-off sponsorships. As Nxeon continues to grow, we want our creators to grow alongside us.

If you're interested, I'd be happy to send over the full details and get you set up.

You can either email me here, or message me on WhatsApp for a faster response and direct support.

Best,

**Santino**
Owner, Nxeon

[nxeon.cloud](https://nxeon.cloud) | [santino@nxeon.cloud](mailto:santino@nxeon.cloud)
WhatsApp: [+84 818 310 619](https://wa.me/84818310619)`;

type CreatorLead = {
  name: string;
  email: string;
  youtubeChannel: string;
  primaryGame: string;
  currentSponsor: string;
  country: string;
  subscriberCount: string;
};

function toLeadRow(c: CreatorLead): LeadRow {
  return {
    email: c.email,
    fullName: c.name,
    name: c.name, // Business name = the creator/channel identity (no separate company).
    category: c.primaryGame, // -> {{game}} via contactVars() (sender.ts)
    // NOTE: Business.website is domain-normalized on import (normalizeDomain() in
    // import.ts strips the path), which would collapse a full YouTube channel URL like
    // "https://www.youtube.com/@Abyss15963" down to just "www.youtube.com" — losing the
    // actual channel. We still set it (harmless, matches what any URL-shaped website
    // column does today) but the FULL clickable channel URL is preserved via
    // `sourceUrl`, which is NOT normalized and is threaded into each contact's
    // ConsentRecord.note as real lawful-basis/provenance evidence (a real, working
    // mechanism this system already has for exactly this purpose).
    website: c.youtubeChannel,
    sourceUrl: c.youtubeChannel,
    country: c.country,
    // No clean structured field fits subscriber count; companySize is the closest real
    // analogue (business "size"/reach) and is otherwise unused for this segment.
    companySize: c.subscriberCount,
    // "Current hosting sponsor" (c.currentSponsor) has NO home anywhere in the
    // Contact/Business schema (no custom-field bag exists — confirmed by reading every
    // Json column in prisma/schema.prisma: none attach to Contact/Business/ImportBatch).
    // Deliberately NOT stuffed into an unrelated field (e.g. `title`) — left out of the
    // DB import rather than silently misrepresented. It remains readable in the
    // original board-card CSV for manual reference.
  };
}

async function main(): Promise<void> {
  const all: CreatorLead[] = JSON.parse(readFileSync(LEADS_JSON, "utf8"));
  console.log(`Loaded ${all.length} cleaned creator leads from ${LEADS_JSON}.`);

  const alreadyContacted = all.filter((c) => c.email.toLowerCase() === ALREADY_CONTACTED_EMAIL);
  const toList = all.filter((c) => c.email.toLowerCase() !== ALREADY_CONTACTED_EMAIL);
  console.log(`  -> ${toList.length} to import into the campaign list, ${alreadyContacted.length} excluded (already contacted today via a separate channel).`);

  // ---- Resolve the sending Brand. Real, already-compliant: physicalPostalAddress is
  // genuinely set (CAN-SPAM requirement), not a placeholder. See run output + final
  // report for why this campaign is NOT pointed at santino@nxeon.cloud/nxeon.cloud.
  const brand = await db.brand.findFirst({ where: { name: "Nxeon" }, select: { id: true, name: true, physicalPostalAddress: true } });
  if (!brand) throw new Error("No 'Nxeon' Brand found — expected the existing, already-compliant sending identity.");
  console.log(`Brand: ${brand.name} (${brand.id}), physicalPostalAddress: "${brand.physicalPostalAddress}"`);

  // ---- Create (or reuse) the dedicated, segmented EmailList.
  let list = await db.emailList.findFirst({ where: { name: LIST_NAME }, select: { id: true } });
  if (!list) {
    list = await db.emailList.create({
      data: { name: LIST_NAME, brandId: brand.id, description: "328 unique creator-sponsorship leads from board card cmuh36ziz02l9hl4m7ws5jczm, minus 179 blank Palworld-placeholder rows, minus 6 in-file duplicate emails, minus Army of Zeus (already contacted today outside this engine)." },
      select: { id: true },
    });
    console.log(`Created EmailList "${LIST_NAME}" (${list.id}).`);
  } else {
    console.log(`Reusing existing EmailList "${LIST_NAME}" (${list.id}).`);
  }

  // ---- Import the 327 into the list (idempotent: safe to re-run).
  const batch = await db.importBatch.create({
    data: {
      name: `Creator sponsorship import ${new Date().toISOString().slice(0, 16)}`,
      source: "script",
      listId: list.id,
      note: "Board card 'Full reachout' (cmuh36ziz02l9hl4m7ws5jczm) CSV — creator sponsorship outreach segment. See scripts/coldemail-creator-campaign-setup.ts.",
    },
    select: { id: true },
  });
  const result = await ingestLeads(toList.map(toLeadRow), {
    store: prismaLeadStore("script"),
    listId: list.id,
    batchId: batch.id,
    recordConsent: true,
    consentSource: "creator sponsorship outreach — board card CSV",
  });
  await db.importBatch.update({
    where: { id: batch.id },
    data: {
      totalRows: result.totalRows,
      inserted: result.inserted,
      updated: result.updated,
      skippedDead: result.skippedDead,
      skippedDup: result.skippedDup,
      skippedInvalid: result.skippedInvalid,
    },
  });
  console.log("Import into campaign list:");
  console.log(`  inserted (new):          ${result.inserted}`);
  console.log(`  updated (existing):      ${result.updated}`);
  console.log(`  skipped dead/suppressed: ${result.skippedDead}`);
  console.log(`  skipped in-file dupes:   ${result.skippedDup}`);
  console.log(`  skipped invalid:         ${result.skippedInvalid}`);
  console.log(`  batch id: ${batch.id}`);

  // ---- Import Army of Zeus too (real lead-DB record) but WITHOUT list membership —
  // the honest "already contacted, not opted out" mechanism (see file header).
  if (alreadyContacted.length > 0) {
    const zeusBatch = await db.importBatch.create({
      data: {
        name: `Creator sponsorship import (already-contacted, no list) ${new Date().toISOString().slice(0, 16)}`,
        source: "script",
        listId: null,
        note: "Army of Zeus — already received a real one-off send today from santino@nxeon.cloud outside this engine. Recorded in the lead DB for reference but deliberately NOT added to any EmailList, so no campaign ever schedules them. Not a Suppression row: they did not opt out.",
      },
      select: { id: true },
    });
    const zeusResult = await ingestLeads(alreadyContacted.map(toLeadRow), {
      store: prismaLeadStore("script"),
      listId: null,
      batchId: zeusBatch.id,
      recordConsent: true,
      consentSource: "creator sponsorship outreach — board card CSV (already contacted 2026-09-25, no list)",
    });
    await db.importBatch.update({
      where: { id: zeusBatch.id },
      data: {
        totalRows: zeusResult.totalRows,
        inserted: zeusResult.inserted,
        updated: zeusResult.updated,
        skippedDead: zeusResult.skippedDead,
        skippedDup: zeusResult.skippedDup,
        skippedInvalid: zeusResult.skippedInvalid,
      },
    });
    console.log(`Army of Zeus recorded (contact id(s): ${zeusResult.contactIds.join(", ") || "none — see skip counts"}), batch ${zeusBatch.id}, list membership: NONE.`);
  }

  // ---- Create the campaign (DRAFT — never launched by this script).
  let campaign = await db.coldCampaign.findFirst({ where: { name: CAMPAIGN_NAME }, select: { id: true, status: true } });
  if (!campaign) {
    campaign = await db.coldCampaign.create({
      data: {
        name: CAMPAIGN_NAME,
        brandId: brand.id,
        listId: list.id,
        // Same send-window convention as every existing hosting-prospect campaign
        // (7–11am America/New_York) — matching this system's own established pacing
        // convention rather than inventing a new one.
        sendWindowStart: 420,
        sendWindowEnd: 660,
        timezone: "America/New_York",
      },
      select: { id: true, status: true },
    });
    console.log(`Created ColdCampaign "${CAMPAIGN_NAME}" (${campaign.id}), status ${campaign.status}.`);
  } else {
    console.log(`Reusing existing ColdCampaign "${CAMPAIGN_NAME}" (${campaign.id}), status ${campaign.status}.`);
  }

  // ---- Create the sequence step (idempotent: only if the campaign has none yet).
  const existingSteps = await db.sequenceStep.count({ where: { campaignId: campaign.id } });
  if (existingSteps === 0) {
    const step = await db.sequenceStep.create({
      data: { campaignId: campaign.id, stepOrder: 1, subject: SUBJECT, bodyMarkdown: BODY_MARKDOWN, delayDays: 0 },
      select: { id: true },
    });
    console.log(`Created SequenceStep 1 (${step.id}).`);
  } else {
    console.log(`Campaign already has ${existingSteps} step(s) — left untouched.`);
  }

  console.log("\nDone. Campaign status is DRAFT — nothing was scheduled or sent.");
  console.log(`campaignId=${campaign.id} listId=${list.id} brandId=${brand.id}`);
  await db.$disconnect();
}

main().catch(async (err) => {
  console.error("Setup failed:", err?.message ?? err);
  await db.$disconnect().catch(() => null);
  process.exit(1);
});

