/**
 * READ-ONLY dry-run verification for the creator-sponsorship campaign created by
 * scripts/coldemail-creator-campaign-setup.ts. Writes NOTHING — no ColdSend rows, no
 * status change, no network call. Two real, code-path proofs:
 *
 *  1. Recipient-count breakdown — the exact same query/logic as
 *     lib/actions-coldemail.ts::previewCampaign() (that function itself can't be
 *     called from a plain script — it's a "use server" action gated by
 *     requireArea("platform"), which needs a real admin HTTP session to resolve).
 *
 *  2. Full message-content rendering — calls lib/coldemail/sender.ts::buildMessage()
 *     DIRECTLY (the exact same pure function the real send worker calls at
 *     worker/coldemail.ts:416, with `track: false` and no sendId, i.e. exactly how a
 *     preview should call it) for a sample of real imported contacts, and asserts the
 *     real compliance guarantees on the output: unsubscribe link present, RFC 8058
 *     headers present, real (non-placeholder) physical address present, {{game}}/
 *     {{firstName}} merge fields correctly substituted per contact.
 *
 * Also prints a REAL pacing projection using the actual warmup/rotation math
 * (lib/coldemail/compliance.ts::warmupDailyCap, lib/coldemail/rotation.ts) against the
 * REAL current state of the brand's only inbox — not an invented number.
 *
 * Usage: npx tsx scripts/coldemail-creator-campaign-dryrun.ts
 */
import { db } from "../lib/db";
import { isSuppressed, requireBrandCompliance, warmupDayIndex, warmupDailyCap, type SuppressionLike } from "../lib/coldemail/compliance";
import { isMailableStatus } from "../lib/coldemail/leaddb";
import { buildMessage, type ContactLike } from "../lib/coldemail/sender";
import { remainingCapacity, isInboxEligible } from "../lib/coldemail/rotation";

const CAMPAIGN_NAME = "Creator Sponsorship Outreach — YouTube (2026-09)";

async function main(): Promise<void> {
  const campaign = await db.coldCampaign.findFirst({
    where: { name: CAMPAIGN_NAME },
    include: { brand: true, steps: true },
  });
  if (!campaign) throw new Error(`Campaign "${CAMPAIGN_NAME}" not found — run the setup script first.`);

  console.log("=".repeat(78));
  console.log(`Campaign: ${campaign.name} (${campaign.id})  status=${campaign.status}`);
  console.log(`Brand: ${campaign.brand.name}  physicalPostalAddress="${campaign.brand.physicalPostalAddress}"`);
  console.log("=".repeat(78));

  // ---------------------------------------------------------------------
  // 1) Recipient-count dry-run — identical logic to previewCampaign()
  //    (lib/actions-coldemail.ts:607-684), reproduced here because that
  //    function requires a real admin request context (requireArea).
  // ---------------------------------------------------------------------
  const missing = requireBrandCompliance(campaign.brand);
  if (missing.length > 0) {
    console.log(`BLOCKED — brand missing: ${missing.map((m) => m.label).join(", ")}`);
    await db.$disconnect();
    return;
  }
  console.log("\n[1] Recipient breakdown (previewCampaign's real logic, reproduced read-only):");

  const members = await db.emailListMember.findMany({
    where: { listId: campaign.listId },
    select: {
      contact: {
        select: { id: true, email: true, emailStatus: true, timesEmailed: true, consentRecords: { select: { id: true }, take: 1 } },
      },
    },
  });
  const suppressions: SuppressionLike[] = await db.suppression.findMany({
    where: { OR: [{ scope: "GLOBAL" }, { scope: "BRAND", brandId: campaign.brandId }] },
    select: { email: true, domain: true, scope: true, brandId: true },
  });
  let suppressed = 0, dead = 0, alreadyEmailed = 0, missingConsent = 0, sendable = 0;
  for (const m of members) {
    if ((m.contact.timesEmailed ?? 0) > 0) alreadyEmailed++;
    if (isSuppressed(m.contact.email, campaign.brandId, suppressions)) { suppressed++; continue; }
    if (!isMailableStatus(m.contact.emailStatus)) { dead++; continue; }
    if (m.contact.consentRecords.length === 0) { missingConsent++; continue; }
    sendable++;
  }
  console.log(`  total=${members.length} suppressed=${suppressed} dead=${dead} alreadyEmailed=${alreadyEmailed} missingConsent=${missingConsent} sendable=${sendable}`);

  // Confirm Army of Zeus is genuinely out of scope (not a list member at all).
  const zeus = await db.contact.findUnique({ where: { email: "iwizardhax2.0@gmail.com" }, select: { id: true } });
  if (zeus) {
    const zeusMembership = await db.emailListMember.findFirst({ where: { listId: campaign.listId, contactId: zeus.id } });
    console.log(`  Army of Zeus list membership for this campaign: ${zeusMembership ? "PRESENT (BUG)" : "absent (correct — excluded)"}`);
  }

  // ---------------------------------------------------------------------
  // 2) Real content rendering via the actual buildMessage() the send worker
  //    uses — proves the exact bytes that WOULD go out, without sending.
  // ---------------------------------------------------------------------
  console.log("\n[2] Rendered message samples (real buildMessage(), track:false, no ColdSend written):");
  const step = campaign.steps[0];
  if (!step) throw new Error("Campaign has no SequenceStep.");

  const sampleContacts = await db.contact.findMany({
    where: { listMembers: { some: { listId: campaign.listId } } },
    select: { id: true, email: true, fullName: true, title: true, business: { select: { name: true, category: true } } },
    take: 4,
    orderBy: { createdAt: "asc" },
  });
  // Also grab one contact whose business has NO category, to prove {{game}} degrades
  // to blank rather than leaking a literal "{{game}}" token.
  const blankGameContact = await db.contact.findFirst({
    where: { listMembers: { some: { listId: campaign.listId } }, business: { category: "" } },
    select: { id: true, email: true, fullName: true, title: true, business: { select: { name: true, category: true } } },
  });
  const samples: ContactLike[] = [...sampleContacts, ...(blankGameContact ? [blankGameContact] : [])];

  for (const c of samples) {
    const msg = buildMessage({
      identity: {
        id: campaign.brand.id,
        name: campaign.brand.name,
        fromName: campaign.brand.fromName,
        fromEmail: campaign.brand.fromEmail,
        replyTo: campaign.brand.replyTo,
        sendingDomain: campaign.brand.sendingDomain,
        physicalPostalAddress: campaign.brand.physicalPostalAddress,
      },
      step: { subject: step.subject, bodyMarkdown: step.bodyMarkdown },
      contact: c,
      track: false, // previews never wrap tracking — matches buildMessage's own contract
    });
    const hasUnsub = /\/api\/coldemail\/unsubscribe\?token=/.test(msg.html);
    const hasListUnsubHeader = !!msg.headers["List-Unsubscribe"] && !!msg.headers["List-Unsubscribe-Post"];
    const hasRealAddress = msg.html.includes(campaign.brand.physicalPostalAddress) && !msg.html.includes("[physical postal address not set]");
    const leakedBrackets = /\[Name\]|\[Creator Name\]|\[GAME\]/.test(msg.html) || /\{\{\s*\w+\s*\}\}/.test(msg.subject + msg.text);
    console.log(`\n  --- ${c.email} (game="${c.business?.category || "(blank)"}") ---`);
    console.log(`  subject: ${msg.subject}`);
    console.log(`  from: ${msg.from}  replyTo: ${msg.replyTo}`);
    console.log(`  unsubscribe link present: ${hasUnsub}`);
    console.log(`  List-Unsubscribe headers present: ${hasListUnsubHeader}`);
    console.log(`  real (non-placeholder) physical address present: ${hasRealAddress}`);
    console.log(`  any unresolved [bracket]/{{token}} leaked into output: ${leakedBrackets}`);
  }

  // ---------------------------------------------------------------------
  // 3) Real pacing projection — actual warmup/rotation functions against the
  //    ACTUAL current inbox + the ACTUAL existing backlog on it.
  // ---------------------------------------------------------------------
  console.log("\n[3] Pacing — real numbers from the live brand/inbox state:");
  const inboxes = await db.inbox.findMany({
    where: { sendingDomain: { brandId: campaign.brandId } },
    select: { id: true, email: true, status: true, dailyCap: true, warmupStartedAt: true, warmupDay: true, minGapSeconds: true, lastSendAt: true, sendingDomain: { select: { spfVerified: true, dkimVerified: true, dmarcVerified: true, domain: true } } },
  });
  for (const ib of inboxes) {
    const dayIdx = warmupDayIndex(ib.warmupStartedAt ?? undefined);
    const cap = warmupDailyCap(dayIdx, ib.dailyCap);
    const authGreen = ib.sendingDomain.spfVerified && ib.sendingDomain.dkimVerified && ib.sendingDomain.dmarcVerified;
    console.log(`  ${ib.email} (${ib.sendingDomain.domain}): status=${ib.status} warmupDay=${dayIdx} todaysCap=${cap} minGapSeconds=${ib.minGapSeconds} authGreen=${authGreen}`);
  }
  const otherQueued = await db.coldSend.count({ where: { campaign: { brandId: campaign.brandId }, status: "QUEUED" } });
  const otherSending = await db.coldCampaign.count({ where: { brandId: campaign.brandId, status: "SENDING" } });
  console.log(`  Existing QUEUED ColdSend rows already competing for this brand's inbox pool: ${otherQueued} (across ${otherSending} SENDING campaign(s) other than this DRAFT one)`);
  const days40 = inboxes[0] ? Math.ceil(members.length / inboxes[0].dailyCap) : null;
  if (days40 !== null) {
    console.log(`  At the existing inbox's own fully-ramped cap (${inboxes[0].dailyCap}/day) with EXCLUSIVE access, ${members.length} recipients would take ~${days40} days.`);
  }
  if (otherQueued > 0) {
    console.log(`  REALITY CHECK: this inbox is NOT exclusive — ${otherQueued} sends from another campaign are already queued ahead of it in the same daily-cap pool. See the final report for what this means.`);
  }

  await db.$disconnect();
}

main().catch(async (err) => {
  console.error("Dry-run failed:", err?.message ?? err);
  await db.$disconnect().catch(() => null);
  process.exit(1);
});

