  const samples: ContactLike[] = [...sampleContacts, ...(blankGameContact ? [blankGameContact] : [])];

  for (const c of samples) {
    const msg = buildMessage({
      identity: {
        id: campaign.brand.id,
        name: campaign.brand.name,
        fromName: campaign.brand.fromName,
        fromEmail: campaign.brand.fromEmail,
        replyTo: campaign.brand.replyTo,
        sendingDomain: campaign.brand.sendingDomain,
        physicalPostalAddress: campaign.brand.physicalPostalAddress,
      },
      step: { subject: step.subject, bodyMarkdown: step.bodyMarkdown },
      contact: c,
      track: false, // previews never wrap tracking — matches buildMessage's own contract
    });
    const hasUnsub = /\/api\/coldemail\/unsubscribe\?token=/.test(msg.html);
    const hasListUnsubHeader = !!msg.headers["List-Unsubscribe"] && !!msg.headers["List-Unsubscribe-Post"];
    const hasRealAddress = msg.html.includes(campaign.brand.physicalPostalAddress) && !msg.html.includes("[physical postal address not set]");
    const leakedBrackets = /\[Name\]|\[Creator Name\]|\[GAME\]/.test(msg.html) || /\{\{\s*\w+\s*\}\}/.test(msg.subject + msg.text);
    console.log(`\n  --- ${c.email} (game="${c.business?.category || "(blank)"}") ---`);
    console.log(`  subject: ${msg.subject}`);
    console.log(`  from: ${msg.from}  replyTo: ${msg.replyTo}`);
    console.log(`  unsubscribe link present: ${hasUnsub}`);
    console.log(`  List-Unsubscribe headers present: ${hasListUnsubHeader}`);
    console.log(`  real (non-placeholder) physical address present: ${hasRealAddress}`);
    console.log(`  any unresolved [bracket]/{{token}} leaked into output: ${leakedBrackets}`);
  }

  // ---------------------------------------------------------------------
  // 3) Real pacing projection — actual warmup/rotation functions against the
  //    ACTUAL current inbox + the ACTUAL existing backlog on it.
  // ---------------------------------------------------------------------
  console.log("\n[3] Pacing — real numbers from the live brand/inbox state:");
  const inboxes = await db.inbox.findMany({
    where: { sendingDomain: { brandId: campaign.brandId } },
    select: { id: true, email: true, status: true, dailyCap: true, warmupStartedAt: true, warmupDay: true, minGapSeconds: true, lastSendAt: true, sendingDomain: { select: { spfVerified: true, dkimVerified: true, dmarcVerified: true, domain: true } } },
  });
  for (const ib of inboxes) {
    const dayIdx = warmupDayIndex(ib.warmupStartedAt ?? undefined);
    const cap = warmupDailyCap(dayIdx, ib.dailyCap);
    const authGreen = ib.sendingDomain.spfVerified && ib.sendingDomain.dkimVerified && ib.sendingDomain.dmarcVerified;
    console.log(`  ${ib.email} (${ib.sendingDomain.domain}): status=${ib.status} warmupDay=${dayIdx} todaysCap=${cap} minGapSeconds=${ib.minGapSeconds} authGreen=${authGreen}`);
  }
  const otherQueued = await db.coldSend.count({ where: { campaign: { brandId: campaign.brandId }, status: "QUEUED" } });
  const otherSending = await db.coldCampaign.count({ where: { brandId: campaign.brandId, status: "SENDING" } });
  console.log(`  Existing QUEUED ColdSend rows already competing for this brand's inbox pool: ${otherQueued} (across ${otherSending} SENDING campaign(s) other than this DRAFT one)`);
  const days40 = inboxes[0] ? Math.ceil(members.length / inboxes[0].dailyCap) : null;
  if (days40 !== null) {
    console.log(`  At the existing inbox's own fully-ramped cap (${inboxes[0].dailyCap}/day) with EXCLUSIVE access, ${members.length} recipients would take ~${days40} days.`);
  }
  if (otherQueued > 0) {
    console.log(`  REALITY CHECK: this inbox is NOT exclusive — ${otherQueued} sends from another campaign are already queued ahead of it in the same daily-cap pool. See the final report for what this means.`);
  }

  await db.$disconnect();
}

main().catch(async (err) => {
  console.error("Dry-run failed:", err?.message ?? err);
  await db.$disconnect().catch(() => null);
  process.exit(1);
});

